UPDATE cards SET insight_title = 'Чистый лист и доверие пути', description_paragraph_1 = 'Шут открывает колоду не случайно: он — точка отсчёта, момент перед первым шагом, когда за плечами ещё нет ни ошибок, ни ожиданий. Сегодня вселенная подталкивает вас сделать что-то впервые, без гарантий и страховки.', description_paragraph_2 = 'Не пытайтесь просчитать всё наперёд — избыточный анализ убивает именно ту лёгкость, ради которой эта карта пришла к вам. Сделайте один маленький, но настоящий шаг в неизвестность, и дорога начнёт открываться сама.', keywords = 'НОВЫЕ НАЧАЛА, СПОНТАННОСТЬ, ДОВЕРИЕ, СВОБОДА' WHERE name = 'Шут';
UPDATE cards SET insight_title = 'Все инструменты уже у вас в руках', description_paragraph_1 = 'Маг стоит за столом, на котором разложены все четыре стихии — у него есть всё необходимое для воплощения замысла. Эта карта говорит: ресурсы, знания и связи, которые вам нужны сегодня, уже находятся в зоне досягаемости.', description_paragraph_2 = 'Дело не в нехватке возможностей, а в готовности соединить намерение с действием. Сформулируйте цель чётко, и вы удивитесь, как быстро обстоятельства начнут выстраиваться в вашу пользу.', keywords = 'СИЛА ВОЛИ, ВОЗМОЖНОСТИ, МАСТЕРСТВО, НАЧИНАНИЯ' WHERE name = 'Маг';
UPDATE cards SET insight_title = 'Знание, которое приходит не через слова', description_paragraph_1 = 'Жрица сидит между двух колонн, на границе видимого и скрытого, и напоминает: не всё, что важно, можно объяснить логикой. Сегодня ваша интуиция знает больше, чем способен сформулировать рассудок.', description_paragraph_2 = 'Если ум настаивает на одном, а внутреннее чувство шепчет другое — прислушайтесь к тише голосу. Дайте себе время на тишину и наблюдение, прежде чем действовать или говорить.', keywords = 'ИНТУИЦИЯ, ТАЙНА, ВНУТРЕННЕЕ ЗНАНИЕ, ТИШИНА' WHERE name = 'Жрица';
UPDATE cards SET insight_title = 'Изобилие рождается из заботы', description_paragraph_1 = 'Императрица окружена цветущим садом — она показывает, что рост не форсируют, а выращивают терпеливым вниманием. Сегодняшний день благоприятен для всего, что связано с заботой: о себе, о деле, об отношениях.', description_paragraph_2 = 'Позвольте себе быть щедрыми — к другим и к собственным потребностям. То, во что вы вкладываете тепло и внимание сейчас, вернётся к вам многократно умноженным позже.', keywords = 'ИЗОБИЛИЕ, ЗАБОТА, ТВОРЧЕСТВО, РОСТ' WHERE name = 'Императрица';
UPDATE cards SET insight_title = 'Порядок как форма зрелой любви', description_paragraph_1 = 'Император держит власть не ради власти, а ради защиты того, что ему дорого. Сегодня день, когда структура, дисциплина и чёткие границы работают на вас сильнее, чем порыв и импульсивность.', description_paragraph_2 = 'Возьмите на себя ответственность за то, что давно требовало решения. Твёрдая, но справедливая позиция сейчас принесёт больше стабильности, чем попытка всем угодить.', keywords = 'СТРУКТУРА, ОТВЕТСТВЕННОСТЬ, СТАБИЛЬНОСТЬ, КОНТРОЛЬ' WHERE name = 'Император';
UPDATE cards SET insight_title = 'Мудрость, проверенная временем', description_paragraph_1 = 'Иерофант — голос традиции, наставника, системы, которая работала для многих до вас. Эта карта приходит, когда стоит довериться проверенному пути, а не изобретать колесо заново.', description_paragraph_2 = 'Поищите совет у того, кто уже прошёл похожий путь, или обратитесь к собственному опыту. Иногда мудрость — это не новое открытие, а готовность принять то, что уже известно.', keywords = 'ТРАДИЦИИ, НАСТАВНИЧЕСТВО, УБЕЖДЕНИЯ, СТРУКТУРА' WHERE name = 'Иерофант';
UPDATE cards SET insight_title = 'Выбор, который говорит о ценностях', description_paragraph_1 = 'Влюблённые — это карта не только романтики, но и важного решения, где сталкиваются голова и сердце. Сегодня перед вами может встать выбор, который на самом деле проверяет, что для вас действительно важно.', description_paragraph_2 = 'Не торопитесь подгонять ответ под чужие ожидания. Загляните внутрь и спросите: какой вариант отзывается искренним «да», а не страхом «нет»?', keywords = 'ВЫБОР, ГАРМОНИЯ, ОТНОШЕНИЯ, ЦЕННОСТИ' WHERE name = 'Влюблённые';
UPDATE cards SET insight_title = 'Победа через направленную волю', description_paragraph_1 = 'Возница держит в руках поводья двух разных по природе сфинксов — управление противоположными силами и есть его искусство. Сегодня успех придёт не через силу, а через ясное направление и собранность.', description_paragraph_2 = 'Сосредоточьтесь на одной цели и не позволяйте противоречивым желаниям тянуть вас в разные стороны. Дисциплина мысли сейчас важнее скорости действия.', keywords = 'ДВИЖЕНИЕ ВПЕРЁД, КОНТРОЛЬ, РЕШИМОСТЬ, ПОБЕДА' WHERE name = 'Колесница';
UPDATE cards SET insight_title = 'Кротость как высшая форма мощи', description_paragraph_1 = 'Женщина на этой карте укрощает льва не борьбой, а спокойствием и нежностью — настоящая сила не кричит и не давит. Сегодня вам пригодится именно такая выдержка: мягкая, но непоколебимая.', description_paragraph_2 = 'Там, где раньше хотелось продавить ситуацию силой, попробуйте терпение и доброту. Они окажутся куда убедительнее в долгосрочной перспективе.', keywords = 'ВНУТРЕННЯЯ СИЛА, ТЕРПЕНИЕ, МЯГКОСТЬ, ВЫДЕРЖКА' WHERE name = 'Сила';
UPDATE cards SET insight_title = 'Свет, который видно только в тишине', description_paragraph_1 = 'Отшельник поднимается в гору один, с фонарём в руке — он ищет ответы не в толпе, а в уединении. Сегодняшний день просит у вас паузы от внешнего шума ради разговора с самим собой.', description_paragraph_2 = 'Не бойтесь ненадолго отойти от компании и обязательств. Именно в одиночестве сейчас придёт ответ, который не находился среди чужих советов.', keywords = 'УЕДИНЕНИЕ, ПОИСК ИСТИНЫ, МУДРОСТЬ, САМОПОЗНАНИЕ' WHERE name = 'Отшельник';
UPDATE cards SET insight_title = 'Цикл поворачивается в вашу пользу', description_paragraph_1 = 'Колесо никогда не стоит на месте — оно поднимает и опускает, и сегодня вы можете почувствовать, как ситуация сдвигается сама, без вашего прямого усилия. Это карта перемен, которые приходят извне.', description_paragraph_2 = 'Не цепляйтесь за контроль над тем, что и так меняется по своим законам. Примите движение колеса с доверием — оно несёт вас вперёд, даже если маршрут пока не виден.', keywords = 'ПЕРЕМЕНЫ, СУДЬБА, ЦИКЛЫ, ВОЗМОЖНОСТИ' WHERE name = 'Колесо Фортуны';
UPDATE cards SET insight_title = 'Истина всегда находит равновесие', description_paragraph_1 = 'Женщина с весами и мечом не судит сгоряча — она взвешивает каждый аргумент, прежде чем выносить решение. Сегодня важно действовать честно и видеть ситуацию без прикрас, даже если правда неудобна.', description_paragraph_2 = 'Если вы ждёте исхода спора, переговоров или решения — справедливость восторжествует, но только если вы сами были честны на всех этапах. Будьте объективны и к себе, и к другим.', keywords = 'БАЛАНС, ЧЕСТНОСТЬ, ПРАВДА, ОТВЕТСТВЕННОСТЬ' WHERE name = 'Справедливость';
UPDATE cards SET insight_title = 'Новый взгляд открывается через паузу', description_paragraph_1 = 'Повешенный висит вниз головой, но на его лице — спокойствие, а не страдание: перевёрнутая перспектива показывает то, что было невидимо в обычном положении. Сегодня стоит сознательно притормозить и посмотреть на проблему иначе.', description_paragraph_2 = 'Если решение не находится — возможно, вы просто смотрите с привычного угла. Дайте себе разрешение ничего не предпринимать какое-то время: пауза — тоже действие.', keywords = 'ПАУЗА, НОВЫЙ ВЗГЛЯД, ОТПУСКАНИЕ, ПЕРЕОСМЫСЛЕНИЕ' WHERE name = 'Повешенный';
UPDATE cards SET insight_title = 'Конец одной главы открывает следующую', description_paragraph_1 = 'Смерть в Таро редко говорит о буквальной утрате — гораздо чаще она про завершение того, что уже отжило своё: привычки, роли, отношений, этапа жизни. Сопротивление этому переходу только продлевает боль.', description_paragraph_2 = 'Позвольте старому уйти без сожаления — на освободившемся месте уже формируется что-то новое. Перемены, которые сейчас кажутся пугающими, на деле освобождают пространство для роста.', keywords = 'ТРАНСФОРМАЦИЯ, ЗАВЕРШЕНИЕ, ОБНОВЛЕНИЕ, ОТПУСКАНИЕ' WHERE name = 'Смерть';
UPDATE cards SET insight_title = 'Алхимия рождается в смешении противоположностей', description_paragraph_1 = 'Ангел на карте перетекает воду из одного сосуда в другой, не проливая ни капли — образ идеального баланса между крайностями. Сегодня умеренность и терпеливое смешивание разных частей жизни принесут больше пользы, чем резкие решения.', description_paragraph_2 = 'Если вас тянет в крайности — работа против отдыха, чувства против разума — поищите среднюю дорогу. Гармония складывается из малых, выверенных шагов, а не из радикальных перемен.', keywords = 'ГАРМОНИЯ, БАЛАНС, ТЕРПЕНИЕ, УМЕРЕННОСТЬ' WHERE name = 'Умеренность';
UPDATE cards SET insight_title = 'Цепи, которые держат добровольно', description_paragraph_1 = 'Фигуры у ног Дьявола прикованы цепями, но эти цепи свободно надеты — стоит лишь снять их. Карта указывает на зависимость, привычку или ограничивающее убеждение, которое держит вас сильнее, чем кажется на первый взгляд.', description_paragraph_2 = 'Спросите себя честно: что в вашей жизни вы выбираете из страха, а не из желания? Признание этого — уже первый шаг к освобождению.', keywords = 'ЗАВИСИМОСТЬ, ИСКУШЕНИЕ, ОГРАНИЧЕНИЯ, ОСВОБОЖДЕНИЕ' WHERE name = 'Дьявол';
UPDATE cards SET insight_title = 'Разрушение, которое расчищает фундамент', description_paragraph_1 = 'Молния бьёт в башню, и то, что строилось на нестабильном основании, рушится внезапно. Болезненно, но честно: эта карта снимает иллюзии быстрее, чем мы готовы их отпустить сами.', description_paragraph_2 = 'Если что-то рассыпается прямо сейчас — не сопротивляйтесь чрезмерно. На месте разрушенной конструкции появится более устойчивый фундамент, построенный уже на правде, а не на удобном самообмане.', keywords = 'ВНЕЗАПНЫЕ ПЕРЕМЕНЫ, КРИЗИС, ОСВОБОЖДЕНИЕ, ПРАВДА' WHERE name = 'Башня';
UPDATE cards SET insight_title = 'Вдохновение и надежда', description_paragraph_1 = 'Звезда — карта возрождения. Она напоминает: даже после самой тёмной ночи приходит рассвет. Сегодня вам открывается новый источник сил.', description_paragraph_2 = 'Доверьтесь интуиции. Идеи, которые приходят к вам — настоящие. Не отмахивайтесь от них.', keywords = 'НАДЕЖДА, ВДОХНОВЕНИЕ, ЯСНОСТЬ, ТВОРЧЕСТВО' WHERE name = 'Звезда';
UPDATE cards SET insight_title = 'То, что прячется в тенях, заслуживает внимания', description_paragraph_1 = 'Луна освещает дорогу неровным, обманчивым светом — формы искажаются, страхи кажутся больше, чем они есть. Сегодня интуиция работает на полную мощность, но вместе с ней могут подняться тревоги и непроверенные опасения.', description_paragraph_2 = 'Не принимайте важных решений, опираясь только на смутное чувство тревоги — дайте туману рассеяться. То, что пугает в темноте, часто оказывается совсем другим при свете дня.', keywords = 'ИНТУИЦИЯ, ИЛЛЮЗИИ, ПОДСОЗНАНИЕ, ОСТОРОЖНОСТЬ' WHERE name = 'Луна';
UPDATE cards SET insight_title = 'Ясность, тепло и заслуженная радость', description_paragraph_1 = 'Солнце — одна из самых благоприятных карт колоды: после трудного пути наступает момент чистой, незамутнённой радости. Сегодня уходят сомнения, и реальность становится понятной и тёплой.', description_paragraph_2 = 'Позвольте себе порадоваться без оговорок — успех сейчас не нужно перепроверять или обесценивать. Делитесь этим светом с другими, он только усилится.', keywords = 'РАДОСТЬ, УСПЕХ, ЯСНОСТЬ, ЭНЕРГИЯ' WHERE name = 'Солнце';
UPDATE cards SET insight_title = 'Зов, который нельзя больше не слышать', description_paragraph_1 = 'Ангел трубит, поднимая фигуры из могил — это пробуждение, призыв оценить пройденный путь и сделать выводы. Сегодня может прийти ощущение, что пора подвести итог и принять решение, которое откладывалось слишком долго.', description_paragraph_2 = 'Будьте честны с собой при этой внутренней проверке: что из прошлого стоит взять с собой, а что — оставить позади? Ответ обычно уже известен, просто требует признания.', keywords = 'ПРОБУЖДЕНИЕ, ИТОГИ, РЕШЕНИЕ, ВОЗРОЖДЕНИЕ' WHERE name = 'Суд';
UPDATE cards SET insight_title = 'Круг замкнулся — и это повод для гордости', description_paragraph_1 = 'Мир завершает старшие арканы: фигура танцует внутри лаврового венка, символизируя успешное завершение долгого цикла. Сегодня — день признания того, что было пройдено, и ощущения целостности.', description_paragraph_2 = 'Не спешите сразу хвататься за следующую цель — позвольте себе на мгновение остановиться и оценить масштаб того, что уже достигнуто. Завершение заслуживает того, чтобы его прожили полностью.', keywords = 'ЗАВЕРШЕНИЕ, ЦЕЛОСТНОСТЬ, ГАРМОНИЯ, ДОСТИЖЕНИЕ' WHERE name = 'Мир';
UPDATE cards SET insight_title = 'Чистый импульс дел, проектов и творческой энергии', description_paragraph_1 = 'Туз Жезлов — это семя, искра в начале нового цикла, связанного с делами, проектами и творческой энергией. Сегодня перед вами открывается возможность начать что-то с нуля, опираясь на стихию огня.', description_paragraph_2 = 'Не упустите этот импульс из-за сомнений — самое важное сейчас — сделать первый шаг, а форма приложится по дороге.', keywords = 'НАЧАЛО, ПОТЕНЦИАЛ, ИМПУЛЬС, ЭНЕРГИЧНЫЙ' WHERE name = 'Туз Жезлов';
UPDATE cards SET insight_title = 'Момент выбора и равновесия', description_paragraph_1 = 'Двойка Жезлов ставит вас перед развилкой, где нужно взвесить два пути или удержать равновесие между двумя силами в сфере дел, проектов и творческой энергии. Решение не обязано быть окончательным — важно сделать осознанный первый выбор.', description_paragraph_2 = 'Не торопите решение искусственно, но и не застревайте в раздумьях слишком долго — оба пути требуют от вас ясности приоритетов.', keywords = 'ВЫБОР, РАВНОВЕСИЕ, ПЛАНИРОВАНИЕ, ЭНЕРГИЧНЫЙ' WHERE name = 'Двойка Жезлов';
UPDATE cards SET insight_title = 'Первые плоды совместных усилий', description_paragraph_1 = 'Тройка Жезлов показывает, что первые усилия в области дел, проектов и творческой энергии начали приносить плоды, и теперь важно не останавливаться на полпути. Сотрудничество и совместная работа усиливают эффект.', description_paragraph_2 = 'Поделитесь успехом с теми, кто помогал на старте — общее дело растёт быстрее, чем одиночное усилие.', keywords = 'РОСТ, СОТРУДНИЧЕСТВО, РАЗВИТИЕ, ЭНЕРГИЧНЫЙ' WHERE name = 'Тройка Жезлов';
UPDATE cards SET insight_title = 'Передышка перед следующим шагом', description_paragraph_1 = 'Четвёрка Жезлов приглашает выдохнуть после рывка в делах, проектах и творческой энергии и закрепить достигнутое, прежде чем двигаться дальше. Это не застой, а заслуженная передышка.', description_paragraph_2 = 'Используйте эту паузу, чтобы укрепить опору, а не как повод вовсе остановиться — скоро снова понадобится двигаться.', keywords = 'СТАБИЛЬНОСТЬ, ОТДЫХ, ЗАКРЕПЛЕНИЕ, ЭНЕРГИЧНЫЙ' WHERE name = 'Четвёрка Жезлов';
UPDATE cards SET insight_title = 'Испытание, которое закаляет', description_paragraph_1 = 'Пятёрка Жезлов говорит о трудностях и трениях в делах, проектах и творческой энергии — самом неприятном, но необходимом этапе на пути к зрелости. Сопротивление сейчас закаляет сильнее, чем лёгкий успех.', description_paragraph_2 = 'Выбирайте битвы осознанно — не каждое противостояние стоит вашей энергии, иногда мудрее отступить, чтобы сохранить силы для главного.', keywords = 'ИСПЫТАНИЕ, НАПРЯЖЕНИЕ, СТОЙКОСТЬ, ЭНЕРГИЧНЫЙ' WHERE name = 'Пятёрка Жезлов';
UPDATE cards SET insight_title = 'Сдвиг в сторону облегчения', description_paragraph_1 = 'Шестёрка Жезлов приносит облегчение после непростого периода в делах, проектах и творческой энергии — напряжение начинает спадать, появляется пространство для маневра.', description_paragraph_2 = 'Используйте это облегчение, чтобы перестроиться и подготовиться к следующему витку — передышка редко бывает вечной.', keywords = 'ОБЛЕГЧЕНИЕ, РАВНОВЕСИЕ, ПРОГРЕСС, ЭНЕРГИЧНЫЙ' WHERE name = 'Шестёрка Жезлов';
UPDATE cards SET insight_title = 'Стойкость на длинной дистанции', description_paragraph_1 = 'Семёрка Жезлов — это испытание выдержки в делах, проектах и творческой энергии, момент, когда нужно либо отстоять позицию, либо честно признать усталость. Долгая дистанция требует терпения, а не героического рывка.', description_paragraph_2 = 'Если позиция всё ещё имеет смысл — держитесь. Если силы уходят в пустоту — честно спросите себя, ради чего вы продолжаете.', keywords = 'ВЫДЕРЖКА, ЗАЩИТА, ТЕРПЕНИЕ, ЭНЕРГИЧНЫЙ' WHERE name = 'Семёрка Жезлов';
UPDATE cards SET insight_title = 'Ускорение и движение к цели', description_paragraph_1 = 'Восьмёрка Жезлов ускоряет события в делах, проектах и творческой энергии — новости, движение, перемены приходят быстрее, чем вы успеваете подготовиться. Сейчас важна гибкость, а не жёсткий план.', description_paragraph_2 = 'Будьте готовы реагировать быстро, но не теряйте голову в спешке — скорость хороша, когда направление выбрано верно.', keywords = 'СКОРОСТЬ, ДВИЖЕНИЕ, ПЕРЕМЕНЫ, ЭНЕРГИЧНЫЙ' WHERE name = 'Восьмёрка Жезлов';
UPDATE cards SET insight_title = 'Почти у финиша, но силы на исходе', description_paragraph_1 = 'Девятка Жезлов показывает, что вы почти у цели в делах, проектах и творческой энергии, но силы уже на пределе. Это карта стойкости перед самым финишем, когда сдаваться особенно не хочется — и не нужно.', description_paragraph_2 = 'Дайте себе разрешение на отдых без чувства вины — забота о себе сейчас не слабость, а условие, чтобы дойти до конца.', keywords = 'ВЫНОСЛИВОСТЬ, ПРЕДЕЛ, НАСТОЙЧИВОСТЬ, ЭНЕРГИЧНЫЙ' WHERE name = 'Девятка Жезлов';
UPDATE cards SET insight_title = 'Точка завершения большого цикла', description_paragraph_1 = 'Десятка Жезлов завершает цикл, связанный с делами, проектами и творческой энергией — это итог, в котором смешаны и плоды труда, и накопившаяся тяжесть. Пора подвести черту и решить, что взять с собой дальше.', description_paragraph_2 = 'Прежде чем начинать новый цикл, осознанно завершите этот — иначе старая тяжесть перейдёт с вами на следующий этап.', keywords = 'ЗАВЕРШЕНИЕ, ИТОГ, ЦИКЛ, ЭНЕРГИЧНЫЙ' WHERE name = 'Десятка Жезлов';
UPDATE cards SET insight_title = 'Юное любопытство, открытое миру', description_paragraph_1 = 'Паж Жезлов — самый юный голос в делах, проектах и творческой энергии, открытый, любопытный, ещё не обременённый опытом. Сегодня полезно посмотреть на привычную ситуацию свежим, почти детским взглядом.', description_paragraph_2 = 'Не бойтесь задавать наивные вопросы и пробовать неочевидные варианты — именно в этой открытости сейчас ваша сила.', keywords = 'ЛЮБОПЫТСТВО, НАЧАЛО, ОТКРЫТОСТЬ, ЭНЕРГИЧНЫЙ' WHERE name = 'Паж Жезлов';
UPDATE cards SET insight_title = 'Порыв, направленный к действию', description_paragraph_1 = 'Рыцарь Жезлов приносит порыв и движение в делах, проектах и творческой энергии — энергию, которая стремится действовать здесь и сейчас, иногда не подождав полного плана.', description_paragraph_2 = 'Прежде чем срываться с места, на секунду остановитесь и проверьте направление — энергия рыцаря сильна, но не всегда точна.', keywords = 'ДЕЙСТВИЕ, ПОРЫВ, ДВИЖЕНИЕ, ЭНЕРГИЧНЫЙ' WHERE name = 'Рыцарь Жезлов';
UPDATE cards SET insight_title = 'Зрелое владение своей стихией', description_paragraph_1 = 'Королева Жезлов воплощает зрелое, уверенное владение стихией огня в применении к делам, проектам и творческой энергии — она знает свою силу и не нуждается в доказательствах.', description_paragraph_2 = 'Доверяйте собственному опыту и интуиции в этой сфере — вам не нужно чужое подтверждение, чтобы действовать уверенно.', keywords = 'ЗРЕЛОСТЬ, УВЕРЕННОСТЬ, ВЛАДЕНИЕ, ЭНЕРГИЧНЫЙ' WHERE name = 'Королева Жезлов';
UPDATE cards SET insight_title = 'Мастерство, проверенное опытом', description_paragraph_1 = 'Король Жезлов — это мастерство, выстроенное годами практики в делах, проектах и творческой энергии. Стабильность и авторитет здесь не случайны, а заслужены опытом.', description_paragraph_2 = 'Используйте накопленный опыт, чтобы поддержать тех, кто только начинает свой путь в этой сфере — настоящий мастер делится знанием.', keywords = 'МАСТЕРСТВО, АВТОРИТЕТ, ОПЫТ, ЭНЕРГИЧНЫЙ' WHERE name = 'Король Жезлов';
UPDATE cards SET insight_title = 'Чистый импульс чувств и отношений', description_paragraph_1 = 'Туз Кубков — это семя, искра в начале нового цикла, связанного с чувствами и отношениями. Сегодня перед вами открывается возможность начать что-то с нуля, опираясь на стихию воды.', description_paragraph_2 = 'Не упустите этот импульс из-за сомнений — самое важное сейчас — сделать первый шаг, а форма приложится по дороге.', keywords = 'НАЧАЛО, ПОТЕНЦИАЛ, ИМПУЛЬС, ЧУВСТВЕННЫЙ' WHERE name = 'Туз Кубков';
UPDATE cards SET insight_title = 'Момент выбора и равновесия', description_paragraph_1 = 'Двойка Кубков ставит вас перед развилкой, где нужно взвесить два пути или удержать равновесие между двумя силами в сфере чувств и отношений. Решение не обязано быть окончательным — важно сделать осознанный первый выбор.', description_paragraph_2 = 'Не торопите решение искусственно, но и не застревайте в раздумьях слишком долго — оба пути требуют от вас ясности приоритетов.', keywords = 'ВЫБОР, РАВНОВЕСИЕ, ПЛАНИРОВАНИЕ, ЧУВСТВЕННЫЙ' WHERE name = 'Двойка Кубков';
UPDATE cards SET insight_title = 'Первые плоды совместных усилий', description_paragraph_1 = 'Тройка Кубков показывает, что первые усилия в области чувств и отношений начали приносить плоды, и теперь важно не останавливаться на полпути. Сотрудничество и совместная работа усиливают эффект.', description_paragraph_2 = 'Поделитесь успехом с теми, кто помогал на старте — общее дело растёт быстрее, чем одиночное усилие.', keywords = 'РОСТ, СОТРУДНИЧЕСТВО, РАЗВИТИЕ, ЧУВСТВЕННЫЙ' WHERE name = 'Тройка Кубков';
UPDATE cards SET insight_title = 'Передышка перед следующим шагом', description_paragraph_1 = 'Четвёрка Кубков приглашает выдохнуть после рывка в чувствах и отношениях и закрепить достигнутое, прежде чем двигаться дальше. Это не застой, а заслуженная передышка.', description_paragraph_2 = 'Используйте эту паузу, чтобы укрепить опору, а не как повод вовсе остановиться — скоро снова понадобится двигаться.', keywords = 'СТАБИЛЬНОСТЬ, ОТДЫХ, ЗАКРЕПЛЕНИЕ, ЧУВСТВЕННЫЙ' WHERE name = 'Четвёрка Кубков';
UPDATE cards SET insight_title = 'Испытание, которое закаляет', description_paragraph_1 = 'Пятёрка Кубков говорит о трудностях и трениях в чувствах и отношениях — самом неприятном, но необходимом этапе на пути к зрелости. Сопротивление сейчас закаляет сильнее, чем лёгкий успех.', description_paragraph_2 = 'Выбирайте битвы осознанно — не каждое противостояние стоит вашей энергии, иногда мудрее отступить, чтобы сохранить силы для главного.', keywords = 'ИСПЫТАНИЕ, НАПРЯЖЕНИЕ, СТОЙКОСТЬ, ЧУВСТВЕННЫЙ' WHERE name = 'Пятёрка Кубков';
UPDATE cards SET insight_title = 'Сдвиг в сторону облегчения', description_paragraph_1 = 'Шестёрка Кубков приносит облегчение после непростого периода в чувствах и отношениях — напряжение начинает спадать, появляется пространство для маневра.', description_paragraph_2 = 'Используйте это облегчение, чтобы перестроиться и подготовиться к следующему витку — передышка редко бывает вечной.', keywords = 'ОБЛЕГЧЕНИЕ, РАВНОВЕСИЕ, ПРОГРЕСС, ЧУВСТВЕННЫЙ' WHERE name = 'Шестёрка Кубков';
UPDATE cards SET insight_title = 'Стойкость на длинной дистанции', description_paragraph_1 = 'Семёрка Кубков — это испытание выдержки в чувствах и отношениях, момент, когда нужно либо отстоять позицию, либо честно признать усталость. Долгая дистанция требует терпения, а не героического рывка.', description_paragraph_2 = 'Если позиция всё ещё имеет смысл — держитесь. Если силы уходят в пустоту — честно спросите себя, ради чего вы продолжаете.', keywords = 'ВЫДЕРЖКА, ЗАЩИТА, ТЕРПЕНИЕ, ЧУВСТВЕННЫЙ' WHERE name = 'Семёрка Кубков';
