UPDATE cards SET insight_title = 'Чистый импульс мыслей, слов и решений', description_paragraph_1 = 'Туз Мечей — это семя, искра в начале нового цикла, связанного с мыслями, словами и решениями. Сегодня перед вами открывается возможность начать что-то с нуля, опираясь на стихию воздуха.', description_paragraph_2 = 'Не упустите этот импульс из-за сомнений — самое важное сейчас — сделать первый шаг, а форма приложится по дороге.', keywords = 'НАЧАЛО, ПОТЕНЦИАЛ, ИМПУЛЬС, ЯСНЫЙ' WHERE name = 'Туз Мечей';
UPDATE cards SET insight_title = 'Момент выбора и равновесия', description_paragraph_1 = 'Двойка Мечей ставит вас перед развилкой, где нужно взвесить два пути или удержать равновесие между двумя силами в сфере мыслей, слов и решений. Решение не обязано быть окончательным — важно сделать осознанный первый выбор.', description_paragraph_2 = 'Не торопите решение искусственно, но и не застревайте в раздумьях слишком долго — оба пути требуют от вас ясности приоритетов.', keywords = 'ВЫБОР, РАВНОВЕСИЕ, ПЛАНИРОВАНИЕ, ЯСНЫЙ' WHERE name = 'Двойка Мечей';
UPDATE cards SET insight_title = 'Первые плоды совместных усилий', description_paragraph_1 = 'Тройка Мечей показывает, что первые усилия в области мыслей, слов и решений начали приносить плоды, и теперь важно не останавливаться на полпути. Сотрудничество и совместная работа усиливают эффект.', description_paragraph_2 = 'Поделитесь успехом с теми, кто помогал на старте — общее дело растёт быстрее, чем одиночное усилие.', keywords = 'РОСТ, СОТРУДНИЧЕСТВО, РАЗВИТИЕ, ЯСНЫЙ' WHERE name = 'Тройка Мечей';
