UPDATE cards SET insight_title = 'Стойкость на длинной дистанции', description_paragraph_1 = 'Семёрка Мечей — это испытание выдержки в мыслях, словах и решениях, момент, когда нужно либо отстоять позицию, либо честно признать усталость. Долгая дистанция требует терпения, а не героического рывка.', description_paragraph_2 = 'Если позиция всё ещё имеет смысл — держитесь. Если силы уходят в пустоту — честно спросите себя, ради чего вы продолжаете.', keywords = 'ВЫДЕРЖКА, ЗАЩИТА, ТЕРПЕНИЕ, ЯСНЫЙ' WHERE name = 'Семёрка Мечей';
UPDATE cards SET insight_title = 'Ускорение и движение к цели', description_paragraph_1 = 'Восьмёрка Мечей ускоряет события в мыслях, словах и решениях — новости, движение, перемены приходят быстрее, чем вы успеваете подготовиться. Сейчас важна гибкость, а не жёсткий план.', description_paragraph_2 = 'Будьте готовы реагировать быстро, но не теряйте голову в спешке — скорость хороша, когда направление выбрано верно.', keywords = 'СКОРОСТЬ, ДВИЖЕНИЕ, ПЕРЕМЕНЫ, ЯСНЫЙ' WHERE name = 'Восьмёрка Мечей';
UPDATE cards SET insight_title = 'Почти у финиша, но силы на исходе', description_paragraph_1 = 'Девятка Мечей показывает, что вы почти у цели в мыслях, словах и решениях, но силы уже на пределе. Это карта стойкости перед самым финишем, когда сдаваться особенно не хочется — и не нужно.', description_paragraph_2 = 'Дайте себе разрешение на отдых без чувства вины — забота о себе сейчас не слабость, а условие, чтобы дойти до конца.', keywords = 'ВЫНОСЛИВОСТЬ, ПРЕДЕЛ, НАСТОЙЧИВОСТЬ, ЯСНЫЙ' WHERE name = 'Девятка Мечей';
UPDATE cards SET insight_title = 'Точка завершения большого цикла', description_paragraph_1 = 'Десятка Мечей завершает цикл, связанный с мыслями, словами и решениями — это итог, в котором смешаны и плоды труда, и накопившаяся тяжесть. Пора подвести черту и решить, что взять с собой дальше.', description_paragraph_2 = 'Прежде чем начинать новый цикл, осознанно завершите этот — иначе старая тяжесть перейдёт с вами на следующий этап.', keywords = 'ЗАВЕРШЕНИЕ, ИТОГ, ЦИКЛ, ЯСНЫЙ' WHERE name = 'Десятка Мечей';
UPDATE cards SET insight_title = 'Юное любопытство, открытое миру', description_paragraph_1 = 'Паж Мечей — самый юный голос в мыслях, словах и решениях, открытый, любопытный, ещё не обременённый опытом. Сегодня полезно посмотреть на привычную ситуацию свежим, почти детским взглядом.', description_paragraph_2 = 'Не бойтесь задавать наивные вопросы и пробовать неочевидные варианты — именно в этой открытости сейчас ваша сила.', keywords = 'ЛЮБОПЫТСТВО, НАЧАЛО, ОТКРЫТОСТЬ, ЯСНЫЙ' WHERE name = 'Паж Мечей';
UPDATE cards SET insight_title = 'Порыв, направленный к действию', description_paragraph_1 = 'Рыцарь Мечей приносит порыв и движение в мыслях, словах и решениях — энергию, которая стремится действовать здесь и сейчас, иногда не подождав полного плана.', description_paragraph_2 = 'Прежде чем срываться с места, на секунду остановитесь и проверьте направление — энергия рыцаря сильна, но не всегда точна.', keywords = 'ДЕЙСТВИЕ, ПОРЫВ, ДВИЖЕНИЕ, ЯСНЫЙ' WHERE name = 'Рыцарь Мечей';
UPDATE cards SET insight_title = 'Зрелое владение своей стихией', description_paragraph_1 = 'Королева Мечей воплощает зрелое, уверенное владение стихией воздуха в применении к мыслям, словам и решениям — она знает свою силу и не нуждается в доказательствах.', description_paragraph_2 = 'Доверяйте собственному опыту и интуиции в этой сфере — вам не нужно чужое подтверждение, чтобы действовать уверенно.', keywords = 'ЗРЕЛОСТЬ, УВЕРЕННОСТЬ, ВЛАДЕНИЕ, ЯСНЫЙ' WHERE name = 'Королева Мечей';
UPDATE cards SET insight_title = 'Мастерство, проверенное опытом', description_paragraph_1 = 'Король Мечей — это мастерство, выстроенное годами практики в мыслях, словах и решениях. Стабильность и авторитет здесь не случайны, а заслужены опытом.', description_paragraph_2 = 'Используйте накопленный опыт, чтобы поддержать тех, кто только начинает свой путь в этой сфере — настоящий мастер делится знанием.', keywords = 'МАСТЕРСТВО, АВТОРИТЕТ, ОПЫТ, ЯСНЫЙ' WHERE name = 'Король Мечей';
UPDATE cards SET insight_title = 'Чистый импульс денег, тела и повседневных дел', description_paragraph_1 = 'Туз Пентаклей — это семя, искра в начале нового цикла, связанного с деньгами, телом и повседневными делами. Сегодня перед вами открывается возможность начать что-то с нуля, опираясь на стихию земли.', description_paragraph_2 = 'Не упустите этот импульс из-за сомнений — самое важное сейчас — сделать первый шаг, а форма приложится по дороге.', keywords = 'НАЧАЛО, ПОТЕНЦИАЛ, ИМПУЛЬС, ПРАКТИЧНЫЙ' WHERE name = 'Туз Пентаклей';
UPDATE cards SET insight_title = 'Момент выбора и равновесия', description_paragraph_1 = 'Двойка Пентаклей ставит вас перед развилкой, где нужно взвесить два пути или удержать равновесие между двумя силами в сфере денег, тела и повседневных дел. Решение не обязано быть окончательным — важно сделать осознанный первый выбор.', description_paragraph_2 = 'Не торопите решение искусственно, но и не застревайте в раздумьях слишком долго — оба пути требуют от вас ясности приоритетов.', keywords = 'ВЫБОР, РАВНОВЕСИЕ, ПЛАНИРОВАНИЕ, ПРАКТИЧНЫЙ' WHERE name = 'Двойка Пентаклей';
UPDATE cards SET insight_title = 'Первые плоды совместных усилий', description_paragraph_1 = 'Тройка Пентаклей показывает, что первые усилия в области денег, тела и повседневных дел начали приносить плоды, и теперь важно не останавливаться на полпути. Сотрудничество и совместная работа усиливают эффект.', description_paragraph_2 = 'Поделитесь успехом с теми, кто помогал на старте — общее дело растёт быстрее, чем одиночное усилие.', keywords = 'РОСТ, СОТРУДНИЧЕСТВО, РАЗВИТИЕ, ПРАКТИЧНЫЙ' WHERE name = 'Тройка Пентаклей';
UPDATE cards SET insight_title = 'Передышка перед следующим шагом', description_paragraph_1 = 'Четвёрка Пентаклей приглашает выдохнуть после рывка в деньгах, теле и повседневных делах и закрепить достигнутое, прежде чем двигаться дальше. Это не застой, а заслуженная передышка.', description_paragraph_2 = 'Используйте эту паузу, чтобы укрепить опору, а не как повод вовсе остановиться — скоро снова понадобится двигаться.', keywords = 'СТАБИЛЬНОСТЬ, ОТДЫХ, ЗАКРЕПЛЕНИЕ, ПРАКТИЧНЫЙ' WHERE name = 'Четвёрка Пентаклей';
UPDATE cards SET insight_title = 'Испытание, которое закаляет', description_paragraph_1 = 'Пятёрка Пентаклей говорит о трудностях и трениях в деньгах, теле и повседневных делах — самом неприятном, но необходимом этапе на пути к зрелости. Сопротивление сейчас закаляет сильнее, чем лёгкий успех.', description_paragraph_2 = 'Выбирайте битвы осознанно — не каждое противостояние стоит вашей энергии, иногда мудрее отступить, чтобы сохранить силы для главного.', keywords = 'ИСПЫТАНИЕ, НАПРЯЖЕНИЕ, СТОЙКОСТЬ, ПРАКТИЧНЫЙ' WHERE name = 'Пятёрка Пентаклей';
UPDATE cards SET insight_title = 'Сдвиг в сторону облегчения', description_paragraph_1 = 'Шестёрка Пентаклей приносит облегчение после непростого периода в деньгах, теле и повседневных делах — напряжение начинает спадать, появляется пространство для маневра.', description_paragraph_2 = 'Используйте это облегчение, чтобы перестроиться и подготовиться к следующему витку — передышка редко бывает вечной.', keywords = 'ОБЛЕГЧЕНИЕ, РАВНОВЕСИЕ, ПРОГРЕСС, ПРАКТИЧНЫЙ' WHERE name = 'Шестёрка Пентаклей';
UPDATE cards SET insight_title = 'Стойкость на длинной дистанции', description_paragraph_1 = 'Семёрка Пентаклей — это испытание выдержки в деньгах, теле и повседневных делах, момент, когда нужно либо отстоять позицию, либо честно признать усталость. Долгая дистанция требует терпения, а не героического рывка.', description_paragraph_2 = 'Если позиция всё ещё имеет смысл — держитесь. Если силы уходят в пустоту — честно спросите себя, ради чего вы продолжаете.', keywords = 'ВЫДЕРЖКА, ЗАЩИТА, ТЕРПЕНИЕ, ПРАКТИЧНЫЙ' WHERE name = 'Семёрка Пентаклей';
